// Contract fixtures are generated by the cloud test tests/test_source_pipeline.py from LABELLED
// TD-schema sample files (ingest -> scoring -> response). Not live data, not an E2E run.
import 'dart:io';

import 'package:copilot/core/net/api_responses.dart';
import 'package:copilot/core/net/recommendation_card.dart';
import 'package:copilot/features/nav_shell/recommend_cards_strip.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

String _fixture(String name) => File('test/fixtures/contract/$name').readAsStringSync();

void main() {
  test('mixed fixture: committable lead first, unknown cards typed unconfirmed + not committable', () {
    final r = ApiResponses.parseRecommend(_fixture('contract_recommend_mixed.json'))!;
    expect(r.cards.first.availability, CardAvailability.available);
    expect(r.cards.first.commitAllowed, isTrue);
    expect(r.cards.first.legacyContract, isFalse);
    final unknown = r.cards.where((c) => c.availability == CardAvailability.unconfirmed).toList();
    expect(unknown, isNotEmpty);
    expect(unknown.every((c) => !c.commitAllowed && c.vacancies == -1), isTrue);
    expect(unknown.every((c) => c.spokenCue.contains('唔可以預留')), isTrue);
  });

  test('all-unknown fixture: no committable card, top cue says nothing reservable, no 首選', () {
    final r = ApiResponses.parseRecommend(_fixture('contract_recommend_all_unknown.json'))!;
    expect(r.cards.any((c) => c.commitAllowed), isFalse);
    expect(r.spokenCue, contains('冇可以預留'));
    expect(r.cards.first.isViable, isTrue);
    expect(r.cards.first.spokenCue, isNot(contains('首選')));
  });

  test('legacy cards derive conservatively and are flagged', () {
    RecommendationCard parse(String card) =>
        ApiResponses.parseRecommend('{"status":"SUCCESS","cards":[$card]}')!.cards.single;
    final stale = parse('{"carpark_id":"A","vacancies":5,"is_stale":true}');
    expect((stale.availability, stale.commitAllowed, stale.legacyContract), (CardAvailability.unconfirmed, false, true));
    final unknown = parse('{"carpark_id":"B","vacancies":-1}');
    expect((unknown.availability, unknown.commitAllowed), (CardAvailability.unconfirmed, false));
    final zero = parse('{"carpark_id":"C","vacancies":0}');
    expect((zero.availability, zero.commitAllowed), (CardAvailability.noAvailability, false));
    final missingVac = parse('{"carpark_id":"D"}');
    expect(missingVac.commitAllowed, isFalse);
    final fresh = parse('{"carpark_id":"E","vacancies":4}');
    expect((fresh.availability, fresh.commitAllowed, fresh.legacyContract), (CardAvailability.available, true, true));
    final bogus = parse('{"carpark_id":"F","vacancies":4,"availability":"MAYBE","commit_allowed":true}');
    expect((bogus.availability, bogus.legacyContract), (CardAvailability.available, true));
    final contradict = parse('{"carpark_id":"G","vacancies":4,"availability":"UNCONFIRMED","commit_allowed":true}');
    expect(contradict.commitAllowed, isFalse); // commit only for committable availability
  });

  testWidgets('unconfirmed card button says it cannot reserve; legacy label visible', (tester) async {
    final r = ApiResponses.parseRecommend(_fixture('contract_recommend_all_unknown.json'))!;
    final legacy = ApiResponses.parseRecommend('{"status":"SUCCESS","cards":[{"carpark_id":"E","name":"E","vacancies":4}]}')!.cards;
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: RecommendCardsStrip(cards: [...r.cards.take(1), ...legacy], onConfirm: (_) {}))));
    expect(tester.widget<FilledButton>(find.byKey(const Key('confirm_card_0'))).onPressed, isNull);
    expect(find.text('空位未確認，唔可以預留'), findsOneWidget);
    expect(find.text('舊版伺服器'), findsOneWidget);
  });
}
